static lstr L1102 = {0, 2194, "// std/float: constants of f64 and reading text. The rest of the functions are built into the compiler.\012\012import * as Str from \"std/string\"\012import * as FloatText from \"std/internal/float\"\012\012/// The ratio of a circle's circumference to its diameter, to `f64` precision.\012export const PI: f64 = 3.141592653589793\012\012/// Reads decimal text as an `f64`: an optional sign, digits with an optional point, and an optional exponent. `nan`, `inf`, spaces and a number too large for `f64` are errors.\012export function parse(text: string): Result<f64, string> uses alloc {\012  const length = Str.length(text)\012  if (length == 0) {\012    return Err(\"empty string\")\012  }\012  let index = 0\012  // An optional sign.\012  if (Str.byteAt(text, index) == 43 || Str.byteAt(text, index) == 45) {\012    index++\012  }\012  // Digits, then an optional point and more digits; at least one digit in all.\012  const wholeStart = index\012  index = skipDigits(text, index)\012  let digitCount = index - wholeStart\012  if (index < length && Str.byteAt(text, index) == 46) {\012    index++\012    const fractionStart = index\012    index = skipDigits(text, index)\012    digitCount += index - fractionStart\012  }\012  if (digitCount == 0) {\012    return Err(\"no digits\")\012  }\012  // An optional exponent with an optional sign and at least one digit.\012  if (index < length && (Str.byteAt(text, index) == 101 || Str.byteAt(text, index) == 69)) {\012    index++\012    if (index < length && (Str.byteAt(text, index) == 43 || Str.byteAt(text, index) == 45)) {\012      index++\012    }\012    const exponentStart = index\012    index = skipDigits(text, index)\012    if (index == exponentStart) {\012      return Err(\"no digits in the exponent\")\012    }\012  }\012  if (index != length) {\012    return Err(\"invalid character in the number\")\012  }\012  // The text follows the grammar, so strtod reads all of it; a number too large reads as infinity.\012  const value = FloatText.parse(text)\012  if (value - value != 0.0) {\012    return Err(\"number does not fit in 64 bits\")\012  }\012  return Ok(value)\012}\012\012function skipDigits(text: string, start: int): int {\012  const length = Str.length(text)\012  let index = start\012  while (index < length && Str.byteAt(text, index) >= 48 && Str.byteAt(text, index) <= 57) {\012    index++\012  }\012  return index\012}\012"};
