static lstr L1106 = {0, 2581, "// std/string: searching, trimming and padding. The rest of the functions are built into the compiler.\012\012import * as Str from \"std/string\"\012\012/// Returns the byte offset of the first `needle` in the text, or `None` when it does not occur.\012/// It is the same as `indexOf`.\012export function find(text: string, needle: string): Option<int> uses alloc {\012  return Str.indexOf(text, needle)\012}\012\012/// Returns the byte offset of the last `needle` in the text, or `None` when it does not occur.\012/// An empty `needle` gives the length of the text.\012export function lastIndexOf(text: string, needle: string): Option<int> uses alloc {\012  let start = Str.length(text) - Str.length(needle)\012  while (start >= 0) {\012    if (Str.slice(text, start, start + Str.length(needle)) is Some(piece)) {\012      if (piece == needle) {\012        return Some(start)\012      }\012    }\012    start--\012  }\012  return None\012}\012\012/// Removes ASCII white space from the start of the text.\012export function trimStart(text: string): string uses alloc {\012  const length = Str.length(text)\012  let start = 0\012  while (start < length && isSpace(Str.byteAt(text, start))) {\012    start++\012  }\012  return Str.sliceFrom(text, start)\012}\012\012/// Removes ASCII white space from the end of the text.\012export function trimEnd(text: string): string uses alloc {\012  let end = Str.length(text)\012  while (end > 0 && isSpace(Str.byteAt(text, end - 1))) {\012    end--\012  }\012  if (Str.slice(text, 0, end) is Some(kept)) {\012    return kept\012  }\012  return text\012}\012\012/// Adds copies of `fill` before the text until it is `width` bytes long. Only whole copies are\012/// added, so a fill of several bytes can leave it shorter.\012export function padStart(text: string, width: int, fill: char): string uses alloc {\012  return `${makePadding(text, width, fill)}${text}`\012}\012\012/// Adds copies of `fill` after the text until it is `width` bytes long. Only whole copies are\012/// added, so a fill of several bytes can leave it shorter.\012export function padEnd(text: string, width: int, fill: char): string uses alloc {\012  return `${text}${makePadding(text, width, fill)}`\012}\012\012function makePadding(text: string, width: int, fill: char): string uses alloc {\012  const fillText = Str.fromChar(fill)\012  const fillLength = Str.length(fillText)\012  if (fillLength == 0) {\012    return \"\"\012  }\012  // Whole copies of fill only, so a multi-byte fill is never split.\012  const count = (width - Str.length(text)) / fillLength\012  if (count > 0) {\012    if (Str.repeat(fillText, count) is Some(padding)) {\012      return padding\012    }\012  }\012  return \"\"\012}\012\012function isSpace(byte: int): bool {\012  return byte == 32 || (byte >= 9 && byte <= 13)\012}\012"};
