static lstr L1130 = {0, 2610, "// std/set: a collection of distinct values, kept in the order they were added.\012//\012// A Set is a value like an Array or a Map: a copy is independent of the original.\012// The type is opaque, so code outside the module cannot reach the map inside it.\012// The items need the same trait as map keys: Hashable.\012\012import * as Maps from \"std/map\"\012\012/// Distinct values in the order they were added. A copy of a set is independent of the original.\012export opaque struct Set<T: Hashable> {\012  members: Map<T, bool>\012}\012\012/// Creates an empty set.\012export function create<T: Hashable>(): Set<T> uses alloc {\012  return Set<T> { members: Map<T, bool> {} }\012}\012\012/// Adds item and returns `true`, or returns `false` and changes nothing when the set already has it.\012export function add<T: Hashable>(mutable set: Set<T>, item: T): bool uses alloc {\012  if (has(set, item)) {\012    return false\012  }\012  set.members[item] = true\012  return true\012}\012\012/// Tells whether the set holds item.\012export function has<T: Hashable>(set: Set<T>, item: T): bool {\012  return set.members[item] is Some(_)\012}\012\012/// Removes item and returns `true`, or returns `false` when the set does not hold it.\012export function remove<T: Hashable>(mutable set: Set<T>, item: T): bool uses alloc {\012  return Maps.remove(mutable set.members, item)\012}\012\012/// Returns the number of values in the set.\012export function size<T: Hashable>(set: Set<T>): int {\012  return Maps.size(set.members)\012}\012\012/// Returns the values of the set as a new array, in the order they were added.\012export function values<T: Hashable>(set: Set<T>): Array<T> uses alloc {\012  return Maps.keys(set.members)\012}\012\012/// Returns a new set with the values of both sets, those of first coming first.\012export function union<T: Hashable>(first: Set<T>, second: Set<T>): Set<T> uses alloc {\012  let result: Set<T> = create()\012  for (const item of values(first)) {\012    add(mutable result, item)\012  }\012  for (const item of values(second)) {\012    add(mutable result, item)\012  }\012  return result\012}\012\012/// Returns a new set with the values of first that second also holds.\012export function intersection<T: Hashable>(first: Set<T>, second: Set<T>): Set<T> uses alloc {\012  let result: Set<T> = create()\012  for (const item of values(first)) {\012    if (has(second, item)) {\012      add(mutable result, item)\012    }\012  }\012  return result\012}\012\012/// Returns a new set with the values of first that second does not hold.\012export function difference<T: Hashable>(first: Set<T>, second: Set<T>): Set<T> uses alloc {\012  let result: Set<T> = create()\012  for (const item of values(first)) {\012    if (!has(second, item)) {\012      add(mutable result, item)\012    }\012  }\012  return result\012}\012"};
