static lstr L1142 = {0, 2319, "// std/time: a monotonic clock for measuring, the wall clock, and sleep. Reading a clock or sleeping is `io`.\012\012import * as Clock from \"std/internal/clock\"\012import * as Tasks from \"std/internal/async\"\012import { AsyncError } from \"std/async\"\012\012/// A point on the monotonic clock, for measuring time. It has no meaning as a date.\012export struct Instant {\012  nanos: int\012}\012\012/// A span of time in nanoseconds.\012export struct Duration {\012  nanos: int\012}\012\012/// Reads the monotonic clock, which never goes back.\012export function now(): Instant uses io {\012  return Instant { nanos: Clock.monotonicNanos() }\012}\012\012/// Gives the time from `since` to now on the monotonic clock.\012export function elapsed(since: Instant): Duration uses io {\012  return Duration { nanos: Clock.monotonicNanos() - since.nanos }\012}\012\012/// Gives the time from `earlier` to `later`, which is negative when `later` comes first.\012export function between(earlier: Instant, later: Instant): Duration {\012  return Duration { nanos: later.nanos - earlier.nanos }\012}\012\012/// Reads the wall clock as milliseconds since 1970-01-01 UTC. The wall clock can jump, so\012/// measure with `now` and `elapsed` instead.\012export function unixMillis(): int uses io {\012  return Clock.wallMillis()\012}\012\012/// Waits at least the duration without blocking other tasks, and gives the time slept. A cancel\012/// of the task ends it with `Err(AsyncError.Cancelled)`.\012export async function sleep(duration: Duration): Result<Duration, AsyncError> uses io, alloc {\012  const slept = await Tasks.sleep(duration.nanos)\012  if (slept < 0) {\012    return Err(AsyncError.Cancelled)\012  }\012  return Ok(Duration { nanos: slept })\012}\012\012/// Gives a duration of `count` nanoseconds.\012export function nanoseconds(count: int): Duration {\012  return Duration { nanos: count }\012}\012\012/// Gives a duration of `count` milliseconds.\012export function milliseconds(count: int): Duration {\012  return Duration { nanos: count * 1000000 }\012}\012\012/// Gives a duration of `count` seconds.\012export function seconds(count: int): Duration {\012  return Duration { nanos: count * 1000000000 }\012}\012\012/// Gives the duration in nanoseconds.\012export function asNanoseconds(duration: Duration): int {\012  return duration.nanos\012}\012\012/// Gives the duration in whole milliseconds, dropping the rest.\012export function asMilliseconds(duration: Duration): int {\012  return duration.nanos / 1000000\012}\012"};
